function create_twitter_accounts(num_accounts) {
    // Initialize the twit library
    import twit

    // Create a list to store the created accounts
    let accounts = []

    // Loop through the number of accounts to create
    for (let i = 0; i < num_accounts; i++) {
        // Create a new Twitter account
        let account = twit.create_account()

        // Add the account to the list
